                         disabled={gameState.initSelectedIds.length !== 3 || !isInteractionAllowed('btn-confirm-init')}
                         onClick={handleConfirmInitSelection} 
                         className="bg-indigo-600 p-3 rounded-full text-white shadow-lg disabled:opacity-50 disabled:grayscale animate-bounce"
                      >
                          <ArrowRight size={24} />
                      </button>
