                               <RotateCcw size={24} />
                           </button>
                       </>
                   )}
                   {(gameState.phase === Phase.RESOURCE_ADD_SELECT || gameState.phase === Phase.RESOURCE_SWAP_SELECT_HAND || gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE) && isInteractive && (
                       <button id="btn-cancel-resource" disabled={!isInteractionAllowed('btn-cancel-resource')} onClick={cancelResourceAction} className="bg-slate-700 p-3 rounded-full text-white shadow-lg disabled:opacity-50">
                           <X size={24} />
                       </button>
                   )}
                   {gameState.phase === Phase.MAIN && isInteractive && (
                       <>
                           {!bottomPlayer.hasAttackedThisTurn && (
                               <button id="btn-attack-phase" disabled={!isInteractionAllowed('btn-attack-phase')} onClick={() => advancePhase(Phase.ATTACK_DECLARE)} className="bg-rose-600 p-3 rounded-full text-white shadow-lg disabled:opacity-50">
                                   <Sword size={24} />
                               </button>
