                   {gameState.phase === Phase.ATTACK_DECLARE && isInteractive && (
                       <button id="btn-confirm-attack" disabled={!isInteractionAllowed('btn-confirm-attack')} onClick={confirmAttack} className="bg-rose-600 px-4 py-2 rounded-full text-white font-bold shadow-lg animate-pulse disabled:opacity-50 disabled:animate-none">
