                   {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && isInteractive && (
                       <button id="btn-confirm-block" disabled={!isInteractionAllowed('btn-confirm-block')} onClick={confirmBlocks} className="bg-blue-600 px-4 py-2 rounded-full text-white font-bold shadow-lg disabled:opacity-50">
