                            id="btn-end-turn"
                            disabled={!isInteractionAllowed('btn-end-turn')}
                            onClick={requestEndTurn}
                            className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 disabled:opacity-50 ${!isInteractionAllowed('btn-end-turn') ? '' : isEndTurnPulse}`}
                        >
                            End Turn
                        </button>
                      </>
                  )}
                  {gameState.phase === Phase.ATTACK_DECLARE && (
                      <button id="btn-confirm-attack" disabled={!isInteractionAllowed('btn-confirm-attack')} onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12 disabled:animate-none">
                          Confirm Attackers
                      </button>
                  )}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === 0 && (
                      <button id="btn-confirm-block" disabled={!isInteractionAllowed('btn-confirm-block')} onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">
                          Confirm Blocks
                      </button>
                  )}

                  {/* CPU Turn Indicator */}
                  {gameState.players[activeDecisionPlayerId].isCpu && gameState.phase !== Phase.INIT_SELECT && (
                      <div className="col-span-2 flex flex-col items-center justify-center h-full gap-2">
                          <div className="w-6 h-6 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                          <span className="text-xs text-indigo-400 font-bold animate-pulse">CPU Thinking...</span>
                      </div>
                  )}
              </div>
          </div>
      </div>

      <div className="absolute top-20 left-4 w-72 z-40 bottom-60 overflow-y-auto space-y-1 pointer-events-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent flex flex-col-reverse">
          {gameState.logs.map((log) => (
              <LogEntry key={log.id} text={log.text} />
          ))}
      </div>
      </>
      )}
    </div>
  );
};

